$ErrorActionPreference = "Stop"

Write-Host "[2DoArchive] Instalador para Windows" -ForegroundColor Cyan
Write-Host "[2DoArchive] Create By RXx8" -ForegroundColor DarkCyan
Write-Host ""

$target = Join-Path $HOME "2DoArchive"
$bin = Join-Path $target "bin"

New-Item -ItemType Directory -Force -Path $target, $bin | Out-Null

# Programa integrado en Base64 para que el instalador no dependa
# de un archivo 2doarchive.py externo.
$encodedProgram = @"

"@

$programBytes = [Convert]::FromBase64String(($encodedProgram -replace '\s',''))
[System.IO.File]::WriteAllBytes(
    (Join-Path $target "2doarchive.py"),
    $programBytes
)

# ============================================================
# Crear comando global: archive
# ============================================================

$launcher = @'
@echo off
set "APP=%USERPROFILE%\2DoArchive\2doarchive.py"

where py >nul 2>&1
if not errorlevel 1 (
    py -3 "%APP%" %*
    exit /b %errorlevel%
)

where python >nul 2>&1
if not errorlevel 1 (
    python "%APP%" %*
    exit /b %errorlevel%
)

echo.
echo [2DoArchive] ERROR: Python 3 no esta instalado.
echo Instala Python 3 y vuelve a ejecutar:
echo irm tinyurl.com/2doarchive-win ^| iex
echo.
exit /b 1
'@

Set-Content `
    -Path (Join-Path $bin "archive.cmd") `
    -Value $launcher `
    -Encoding ASCII

# ============================================================
# Configurar PATH del usuario
# No requiere permisos de administrador.
# ============================================================

$userPath = [Environment]::GetEnvironmentVariable("Path", "User")

if ([string]::IsNullOrWhiteSpace($userPath)) {
    $pathItems = @()
}
else {
    $pathItems = $userPath -split ';' |
        Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
}

if ($pathItems -notcontains $bin) {
    $newUserPath = ($pathItems + $bin) -join ';'
    [Environment]::SetEnvironmentVariable(
        "Path",
        $newUserPath,
        "User"
    )
}

# ============================================================
# Carpeta de descargas
# ============================================================

$downloadFolder = Join-Path $HOME "Carpeta Descargas Archive-ORG"
New-Item -ItemType Directory -Force -Path $downloadFolder | Out-Null

# ============================================================
# Archivo de ejecución local
# ============================================================

$runBat = @'
@echo off
set "APP=%~dp02doarchive.py"

where py >nul 2>&1
if not errorlevel 1 (
    py -3 "%APP%" %*
    exit /b %errorlevel%
)

python "%APP%" %*
'@

Set-Content `
    -Path (Join-Path $target "run.bat") `
    -Value $runBat `
    -Encoding ASCII

# ============================================================
# Verificación
# ============================================================

$installedProgram = Join-Path $target "2doarchive.py"
$installedCommand = Join-Path $bin "archive.cmd"

if (-not (Test-Path $installedProgram)) {
    throw "No se pudo instalar 2doarchive.py."
}

if (-not (Test-Path $installedCommand)) {
    throw "No se pudo crear el comando archive."
}

Write-Host ""
Write-Host "============================================" -ForegroundColor Green
Write-Host "     2DoArchive instalado correctamente" -ForegroundColor Green
Write-Host "============================================" -ForegroundColor Green
Write-Host ""
Write-Host "Programa:"
Write-Host "  $target\2doarchive.py"
Write-Host ""
Write-Host "Descargas:"
Write-Host "  $downloadFolder"
Write-Host ""
Write-Host "Comando:"
Write-Host "  archive" -ForegroundColor Yellow
Write-Host ""
Write-Host "Cierra esta PowerShell y abre una nueva." -ForegroundColor Yellow
Write-Host "Después escribe: archive" -ForegroundColor Yellow
Write-Host ""
